import { useState, useCallback, useEffect } from 'react';
import { getGrade, generateId } from '../utils/helpers';
// Grading handled server-side

const API = 'http://localhost:5000/api';

// ── HTTP helpers ─────────────────────────────────────────────
const getToken = () => localStorage.getItem('examai_token');

const api = async (method, path, body) => {
  const res = await fetch(`${API}${path}`, {
    method,
    headers: {
      'Content-Type': 'application/json',
      ...(getToken() ? { Authorization: `Bearer ${getToken()}` } : {}),
    },
    ...(body ? { body: JSON.stringify(body) } : {}),
  });
  const data = await res.json();
  if (!res.ok) throw new Error(data.error || 'Request failed');
  return data;
};

export const useStore = () => {
  const [currentUser,  setCurrentUser]  = useState(() => {
    try { return JSON.parse(localStorage.getItem('examai_user')) || null; } catch { return null; }
  });
  const [currentStudent, setCurrentStudent] = useState(() => {
    try { return JSON.parse(localStorage.getItem('examai_student')) || null; } catch { return null; }
  });

  // Local cache states (loaded from API)
  const [exams,       setExams]       = useState([]);
  const [questions,   setQuestions]   = useState([]);   // per-exam cache
  const [submissions, setSubmissions] = useState([]);
  const [results,     setResults]     = useState([]);
  const [students,    setStudents]    = useState([]);
  const [toasts,      setToasts]      = useState([]);

  // ── Toasts ──────────────────────────────────────────────────
  const addToast = useCallback((msg, type = 'info') => {
    const id = generateId();
    setToasts(t => [...t, { id, msg, type }]);
    setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 3500);
  }, []);

  // ── Load exams on login ──────────────────────────────────────
  useEffect(() => {
    if (!currentUser) return;
    loadExams();
    if (currentUser.role === 'admin') loadStudents();
    if (currentUser.role === 'student' && currentStudent) loadStudentSubmissions();
  }, [currentUser]);

  const loadExams = async () => {
    try {
      const data = await api('GET', '/exams');
      setExams(data);
    } catch (e) { addToast('Failed to load exams: ' + e.message, 'error'); }
  };

  const loadStudents = async () => {
    try {
      const data = await api('GET', '/students');
      setStudents(data);
    } catch (e) { console.error('load students:', e); }
  };

  const loadStudentSubmissions = async () => {
    try {
      const sid  = currentStudent?.student_id;
      if (!sid) return;
      const subs = await api('GET', `/submissions/student/${sid}`);
      setSubmissions(subs);
      // Load results for each submission
      const resArr = await Promise.all(
        subs.map(s => api('GET', `/submissions/result/${s.submission_id}`).catch(() => null))
      );
      setResults(resArr.filter(Boolean));
    } catch (e) { console.error('load submissions:', e); }
  };

  // ── Auth ────────────────────────────────────────────────────
  const login = async (email, password) => {
    try {
      const data = await api('POST', '/auth/login', { email, password });
      localStorage.setItem('examai_token',   data.token);
      localStorage.setItem('examai_user',    JSON.stringify(data.user));
      localStorage.setItem('examai_student', JSON.stringify(data.student));
      setCurrentUser(data.user);
      setCurrentStudent(data.student);
      return true;
    } catch (e) {
      addToast(e.message, 'error');
      return false;
    }
  };

  const register = async (name, email, password, role, extra = {}) => {
    try {
      const data = await api('POST', '/auth/register', { name, email, password, ...extra });
      localStorage.setItem('examai_token',   data.token);
      localStorage.setItem('examai_user',    JSON.stringify(data.user));
      localStorage.setItem('examai_student', JSON.stringify(data.student));
      setCurrentUser(data.user);
      setCurrentStudent(data.student);
      return true;
    } catch (e) {
      addToast(e.message, 'error');
      return false;
    }
  };

  const logout = () => {
    localStorage.removeItem('examai_token');
    localStorage.removeItem('examai_user');
    localStorage.removeItem('examai_student');
    setCurrentUser(null);
    setCurrentStudent(null);
    setExams([]);
    setQuestions([]);
    setSubmissions([]);
    setResults([]);
    setStudents([]);
  };

  // ── Exam visibility ──────────────────────────────────────────
  const getVisibleExams = () => {
    if (!currentUser) return [];
    if (currentUser.role === 'admin') return exams.filter(e => e.created_by === currentUser.user_id);
    return exams.filter(e => e.status === 'published');
  };

  // ── Questions (cached locally per exam) ─────────────────────
  const getExamQuestions = (examId) => questions.filter(q => q.exam_id === examId);

  const loadExamQuestions = async (examId) => {
    // Don't reload if already cached
    if (questions.some(q => q.exam_id === examId)) return;
    try {
      const qs = await api('GET', `/questions/${examId}`);
      setQuestions(prev => {
        const filtered = prev.filter(q => q.exam_id !== examId);
        return [...filtered, ...qs];
      });
    } catch (e) { console.error('load questions:', e); }
  };

  const shuffleArray = (arr) => {
    const a = [...arr];
    for (let i = a.length - 1; i > 0; i--) {
      const j = Math.floor(Math.random() * (i + 1));
      [a[i], a[j]] = [a[j], a[i]];
    }
    return a;
  };

  const getShuffledExamQuestions = (examId) => {
    const qs = shuffleArray(questions.filter(q => q.exam_id === examId));
    return qs.map(q => {
      if (q.question_type === 'MCQ' && q.options) {
        const shuffledOptions  = shuffleArray(q.options);
        const correctIndex     = shuffledOptions.findIndex(o => o.is_correct);
        const newCorrectAnswer = ['A','B','C','D'][correctIndex];
        return { ...q, options: shuffledOptions, correct_answer: newCorrectAnswer };
      }
      return { ...q };
    });
  };

  // ── Create Exam ──────────────────────────────────────────────
  const createExam = async (examData) => {
    try {
      const exam = await api('POST', '/exams', examData);
      setExams(e => [...e, exam]);
      return exam;
    } catch (e) { addToast('Failed to create exam: ' + e.message, 'error'); return null; }
  };

  const publishExam = async (examId) => {
    try {
      const res = await api('POST', `/exams/${examId}/publish`);
      if (res?.error) return res;
      setExams(es => es.map(e => e.exam_id === examId ? { ...e, status: 'published' } : e));
    } catch (e) { addToast('Failed to publish: ' + e.message, 'error'); }
  };

  const unpublishExam = async (examId) => {
    try {
      await api('POST', `/exams/${examId}/unpublish`);
      setExams(es => es.map(e => e.exam_id === examId ? { ...e, status: 'draft' } : e));
    } catch (e) { addToast('Failed to unpublish: ' + e.message, 'error'); }
  };

  // ── Add Questions ────────────────────────────────────────────
  const addQuestions = async (qs, examTotal) => {
    try {
      // Client-side marks validation
      const examId    = qs[0]?.exam_id;
      const existing  = questions.filter(q => q.exam_id === examId);
      const usedMarks = existing.reduce((s, q) => s + Number(q.marks), 0);
      const existingTexts = existing.map(q => q.question_text.trim().toLowerCase());

      const toSend = [];
      let running  = usedMarks;
      for (const q of qs) {
        const qm = Number(q.marks);
        if (existingTexts.includes(q.question_text.trim().toLowerCase())) continue;
        if (examTotal && running + qm > examTotal) continue;
        toSend.push(q);
        running += qm;
        existingTexts.push(q.question_text.trim().toLowerCase());
      }
      if (!toSend.length) return;

      const saved = await api('POST', '/questions', toSend);
      setQuestions(prev => {
        const filtered = prev.filter(q => q.exam_id !== examId);
        return [...filtered, ...existing, ...saved];
      });
    } catch (e) { addToast('Failed to save questions: ' + e.message, 'error'); }
  };

  const removeQuestion = async (questionId) => {
    try {
      await api('DELETE', `/questions/${questionId}`);
      setQuestions(qs => qs.filter(q => q.question_id !== questionId));
    } catch (e) { addToast('Failed to remove question: ' + e.message, 'error'); }
  };

  // ── Submissions ──────────────────────────────────────────────
  const getStudentSid = () => currentStudent?.student_id || currentUser?.user_id;

  const startSubmission = async (examId) => {
    try {
      const sid = getStudentSid();
      const sub = await api('POST', '/submissions/start', { exam_id: examId, student_id: sid });
      return sub;
    } catch (e) { addToast('Failed to start exam: ' + e.message, 'error'); return null; }
  };

  const submitExam = async (submissionId, answerMap, examId, cheated = false) => {
    // Send raw answers to backend — all grading happens server-side
    try {
      const result = await api('POST', '/submissions/submit', {
        submission_id: submissionId,
        cheated: cheated,
        answers:       answerMap,
        exam_id:       examId,
        student_id:    getStudentSid(),
      });
      setSubmissions(s => s.map(sub =>
        sub.submission_id === submissionId ? { ...sub, status: 'submitted', submit_time: new Date().toISOString() } : sub
      ));
      const finalResult = cheated ? {...result, cheating_detected: true, total_score: 0, grade: 'F'} : result;
      setResults(r => [...r.filter(x => x.submission_id !== submissionId), finalResult]);
      return result;
    } catch (e) {
      addToast('Failed to submit: ' + e.message, 'error');
      return null;
    }
  };

  // ── Result helpers ───────────────────────────────────────────
  const getResult = (subId) => results.find(r => r.submission_id === subId);

  const getStudentSubmissions = () => submissions.filter(s => s.status === 'submitted');

  const getSubmissionAnswers = () => []; // handled server-side

  // ── Lookup helpers ───────────────────────────────────────────
  const getUserById = (uid) => {
    const s = students.find(s => s.user_id === uid);
    if (s) return { user_id: s.user_id, name: s.name, email: s.email };
    return null;
  };

  const getStudentById = (uid) => students.find(s => s.user_id === uid);

  return {
    // state
    currentUser, currentStudent, exams, questions, submissions, results, students,
    toasts, setToasts,
    // auth
    login, register, logout,
    // exam
    createExam, publishExam, unpublishExam,
    getVisibleExams, getExamQuestions, loadExamQuestions,
    getShuffledExamQuestions,
    // questions
    addQuestions, removeQuestion,
    // student
    getStudentById, getUserById, getStudentSid,
    loadStudentSubmissions,
    // submission
    startSubmission, submitExam,
    getSubmissionAnswers, getResult, getStudentSubmissions,
    // reload helpers
    loadExams,
    // ui
    addToast,
  };
};
